-- Legacy articles: all 65 known tsquirrel.com article slugs (scraped July 2026)
-- These map old PHP IDs 16-82 to their Google-indexed slug URLs
-- Used by the legacy route handler to serve /{slug} → 200 with real content

CREATE TABLE IF NOT EXISTS legacy_articles (
  id INTEGER PRIMARY KEY,        -- original PHP article ID
  slug VARCHAR(300) UNIQUE NOT NULL,  -- original URL slug e.g. "drapeau-francais-le-retour-dun-symbole-apres-les-attentats-55"
  title TEXT NOT NULL,
  description TEXT,
  source_url TEXT,               -- external link the article pointed to
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

ON CONFLICT (id) DO NOTHING;
